def private_top2(data, epsilon, rng):
    candidates = ["A", "B", "C", "D"]
    counts = {cat: 0 for cat in candidates}
    for item in data:
        if item in counts:
            counts[item] += 1

    winners = []
    epsilon_round = epsilon / 2.0
    scale = 1.0 / epsilon_round

    for _ in range(2):
        noisy_scores = []
        for cat in candidates:
            noise = rng.laplace(0.0, scale)
            noisy_scores.append(counts[cat] + noise)

        max_idx = int(np.argmax(noisy_scores))
        winner = candidates.pop(max_idx)
        winners.append(winner)

    return winners

